<script>
"use strict";
/* ---------- small helpers ---------- */
const TAU = Math.PI*2;
const clampB = v => v<0?0:v>255?255:v;
const scaleC = (c,f)=>[clampB(c[0]*f),clampB(c[1]*f),clampB(c[2]*f)];
const mixC = (a,b,t)=>[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t];
const rgb = c=>`rgb(${c[0]|0},${c[1]|0},${c[2]|0})`;

/* rotate local vector by Ry(yaw)*Rx(pitch) */
function applyM(vx,vy,vz,yaw,pitch){
  const cp=Math.cos(pitch), sp=Math.sin(pitch);
  const y1=vy*cp - vz*sp, z1=vy*sp + vz*cp, x1=vx;
  const cy=Math.cos(yaw), sy=Math.sin(yaw);
  return [x1*cy + z1*sy, y1, -x1*sy + z1*cy];
}

/* fixed world light + halfway vector */
const Lr=[-0.35,0.55,0.78]; const Ll=Math.hypot(Lr[0],Lr[1],Lr[2]);
const L=[Lr[0]/Ll,Lr[1]/Ll,Lr[2]/Ll];
const Hr=[L[0]+0,L[1]+0,L[2]+1]; const Hl=Math.hypot(Hr[0],Hr[1],Hr[2]);
const H=[Hr[0]/Hl,Hr[1]/Hl,Hr[2]/Hl];

/* ---------- palettes ---------- */
function pal(light,mid,dark){
  return {
    light, mid, dark,
    sh: rgb(scaleC(dark,0.55)),
    hi: rgb(scaleC(light,1.02)),
    fl: rgb(scaleC(mid,1.12)),
    edge: mixC(mid,dark,0.28)
  };
}
const PAL = {
  goldHero: pal([255,244,200],[214,168,74],[104,74,24]),
  bronze:   pal([242,188,132],[176,105,52],[84,45,18]),
  silver:   pal([250,252,255],[184,194,204],[80,90,102]),
  gold:     pal([255,238,170],[220,175,70],[100,72,22]),
  obsidian: pal([120,126,142],[44,46,56],[8,8,12])
};

/* ---------- coin face texture ---------- */
function embossText(ctx,t,x,y,p,d){
  ctx.fillStyle=p.sh; ctx.fillText(t,x+d,y+d);
  ctx.fillStyle=p.hi; ctx.fillText(t,x-d,y-d);
  ctx.fillStyle=p.fl; ctx.fillText(t,x,y);
}
function circularText(ctx,text,cx,cy,r,startDeg,stepDeg,font,p,flip){
  ctx.save(); ctx.font=font; ctx.textAlign='center'; ctx.textBaseline='middle';
  for(let i=0;i<text.length;i++){
    const rad=(startDeg+stepDeg*i)*Math.PI/180;
    const x=cx+r*Math.sin(rad), y=cy-r*Math.cos(rad);
    ctx.save(); ctx.translate(x,y); ctx.rotate(rad+(flip?Math.PI:0));
    embossText(ctx,text[i],0,0,p,0.8);
    ctx.restore();
  }
  ctx.restore();
}
function starPath(ctx,cx,cy,rO,rI){
  ctx.beginPath();
  for(let i=0;i<10;i++){
    const a=-Math.PI/2 + i*Math.PI/5, r=i%2?rI:rO;
    const x=cx+Math.cos(a)*r, y=cy+Math.sin(a)*r;
    i?ctx.lineTo(x,y):ctx.moveTo(x,y);
  }
  ctx.closePath();
}
function embossStar(ctx,cx,cy,rO,rI,p,d){
  ctx.fillStyle=p.sh; starPath(ctx,cx+d,cy+d,rO,rI); ctx.fill();
  ctx.fillStyle=p.hi; starPath(ctx,cx-d,cy-d,rO,rI); ctx.fill();
  ctx.fillStyle=p.fl; starPath(ctx,cx,cy,rO,rI); ctx.fill();
}

function makeCoinFace(S,p,mode,o){
  const cv=document.createElement('canvas'); cv.width=cv.height=S;
  const ctx=cv.getContext('2d');
  const c=S/2, Rt=S/2-4;

  // metallic base
  const g=ctx.createRadialGradient(S*0.38,S*0.32,S*0.04, c,c,Rt);
  g.addColorStop(0,rgb(scaleC(p.light,1.0)));
  g.addColorStop(0.45,rgb(p.mid));
  g.addColorStop(0.82,rgb(scaleC(p.mid,0.82)));
  g.addColorStop(1,rgb(p.dark));
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(c,c,Rt,0,TAU); ctx.fill();

  // brushed radial streaks
  ctx.save(); ctx.beginPath(); ctx.arc(c,c,Rt,0,TAU); ctx.clip();
  ctx.globalAlpha=0.05; ctx.strokeStyle=rgb(p.light); ctx.lineWidth=1;
  for(let i=0;i<220;i++){
    const a=i/220*TAU;
    ctx.beginPath(); ctx.moveTo(c,c);
    ctx.lineTo(c+Math.cos(a)*Rt, c+Math.sin(a)*Rt); ctx.stroke();
  }
  ctx.restore(); ctx.globalAlpha=1;

  // outer bevel rings
  ctx.lineWidth=Rt*0.05; ctx.strokeStyle=rgb(scaleC(p.dark,0.9));
  ctx.beginPath(); ctx.arc(c,c,Rt*0.965,0,TAU); ctx.stroke();
  ctx.lineWidth=Rt*0.02; ctx.strokeStyle=rgb(scaleC(p.light,1.0));
  ctx.beginPath(); ctx.arc(c,c,Rt*0.9,0,TAU); ctx.stroke();
  // inner field ring
  ctx.lineWidth=Rt*0.012; ctx.strokeStyle=p.sh;
  ctx.beginPath(); ctx.arc(c,c,Rt*0.76,0,TAU); ctx.stroke();
  ctx.strokeStyle=p.hi;
  ctx.beginPath(); ctx.arc(c,c,Rt*0.745,0,TAU); ctx.stroke();

  const F=(w,s)=>`${w} ${Math.round(S*s)}px "Hoefler Text",Georgia,serif`;

  // arced text
  const top=o.top, bot=o.bottom;
  const stepT=Math.min(9,150/Math.max(1,top.length-1));
  circularText(ctx,top,c,c,Rt*0.84,-(stepT*(top.length-1))/2,stepT,F('700',0.052),p,false);
  const stepB=Math.min(9,150/Math.max(1,bot.length-1));
  circularText(ctx,bot,c,c,Rt*0.84,180+(stepB*(bot.length-1))/2,-stepB,F('700',0.052),p,true);

  if(mode==='emblem'){
    embossStar(ctx,c,c-Rt*0.44,Rt*0.11,Rt*0.045,p,1);
    ctx.font=F('700',0.24); ctx.textAlign='center'; ctx.textBaseline='middle';
    embossText(ctx,o.mono,c,c-Rt*0.02,p,1.6);
    ctx.font=F('600',0.052); 
    embossText(ctx,o.small,c,c+Rt*0.34,p,0.8);
    // laurel dots
    for(let s=-1;s<=1;s+=2){
      for(let k=0;k<6;k++){
        const a=Math.PI/2 + s*(0.5+k*0.16);
        const x=c+Math.cos(a)*Rt*0.5, y=c+Math.sin(a)*Rt*0.5+Rt*0.02;
        ctx.fillStyle=p.hi; ctx.beginPath(); ctx.arc(x-0.6,y-0.6,Rt*0.012,0,TAU); ctx.fill();
        ctx.fillStyle=p.fl; ctx.beginPath(); ctx.arc(x,y,Rt*0.012,0,TAU); ctx.fill();
      }
    }
  } else { // denom
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.font=F('600',0.045);
    embossText(ctx,'DENOMINATION',c,c-Rt*0.32,p,0.7);
    ctx.font=F('700',0.185);
    embossText(ctx,o.big,c,c-Rt*0.01,p,1.5);
    ctx.font=F('600',0.075);
    embossText(ctx,o.small,c,c+Rt*0.24,p,0.9);
    // tick ring
    for(let k=0;k<72;k++){
      const a=k/72*TAU;
      const x1=c+Math.cos(a)*Rt*0.66, y1=c+Math.sin(a)*Rt*0.66;
      const x2=c+Math.cos(a)*Rt*0.70, y2=c+Math.sin(a)*Rt*0.70;
      ctx.strokeStyle=k%2?p.hi:p.sh; ctx.lineWidth=Rt*0.006;
      ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
    }
  }
  return cv;
}

/* ---------- 3D coin renderer ---------- */
function drawCoin3D(ctx, o){
  const {cx,cy,R,h,yaw,pitch,frontTex,backTex,p,S,seg}=o;
  const half=h/2;
  const Ux=applyM(1,0,0,yaw,pitch);
  const Vy=applyM(0,1,0,yaw,pitch);
  const N =applyM(0,0,1,yaw,pitch);
  const su=[Ux[0],-Ux[1]], sv=[Vy[0],-Vy[1]];   // projected face basis (unit)
  const front = N[2]>=0;
  const Nf = front? N : [-N[0],-N[1],-N[2]];
  const faceCx=cx+half*Nf[0], faceCy=cy-half*Nf[1];
  const farCx =cx-half*Nf[0], farCy =cy+half*Nf[1];
  const edgeCol=p.edge;

  // backfill far face (prevents seams)
  ctx.fillStyle=rgb(scaleC(edgeCol,0.55));
  ctx.beginPath();
  for(let i=0;i<=48;i++){const a=i/48*TAU;
    const x=farCx+Math.cos(a)*R*su[0]+Math.sin(a)*R*sv[0];
    const y=farCy+Math.cos(a)*R*su[1]+Math.sin(a)*R*sv[1];
    i?ctx.lineTo(x,y):ctx.moveTo(x,y);}
  ctx.closePath(); ctx.fill();

  // build ops
  const ops=[];
  ops.push({type:'face', z:half*Nf[2]});
  for(let i=0;i<seg;i++){
    const a0=i/seg*TAU, a1=(i+1)/seg*TAU, am=(a0+a1)/2;
    const d0=applyM(Math.cos(a0),Math.sin(a0),0,yaw,pitch);
    const d1=applyM(Math.cos(a1),Math.sin(a1),0,yaw,pitch);
    const dm=applyM(Math.cos(am),Math.sin(am),0,yaw,pitch);
    const fx0=cx+R*d0[0]+half*N[0], fy0=cy-(R*d0[1]+half*N[1]);
    const fx1=cx+R*d1[0]+half*N[0], fy1=cy-(R*d1[1]+half*N[1]);
    const bx1=cx+R*d1[0]-half*N[0], by1=cy-(R*d1[1]-half*N[1]);
    const bx0=cx+R*d0[0]-half*N[0], by0=cy-(R*d0[1]-half*N[1]);
    let diff=dm[0]*L[0]+dm[1]*L[1]+dm[2]*L[2]; if(diff<0)diff=0;
    let sh=0.30+0.72*diff; if(i%2)sh*=0.64;
    ops.push({type:'edge', z:R*dm[2],
      pts:[[fx0,fy0],[fx1,fy1],[bx1,by1],[bx0,by0]],
      col:rgb(scaleC(edgeCol,sh))});
  }
  ops.sort((a,b)=>a.z-b.z);

  // face path (screen)
  const facePath=new Path2D();
  for(let i=0;i<=64;i++){const a=i/64*TAU;
    const x=faceCx+Math.cos(a)*R*su[0]+Math.sin(a)*R*sv[0];
    const y=faceCy+Math.cos(a)*R*su[1]+Math.sin(a)*R*sv[1];
    i?facePath.lineTo(x,y):facePath.moveTo(x,y);}
  facePath.closePath();

  const drawFace=()=>{
    ctx.save(); ctx.clip(facePath);
    const k=2*R/S, mir=front?1:-1;
    const A=mir*k*su[0], B=mir*k*su[1], C=-k*sv[0], D=-k*sv[1];
    const E=faceCx-(S/2)*(A+C), Fm=faceCy-(S/2)*(B+D);
    ctx.setTransform(A,B,C,D,E,Fm);
    ctx.drawImage(front?frontTex:backTex,0,0);
    ctx.setTransform(1,0,0,1,0,0);
    // specular
    let spec=Nf[0]*H[0]+Nf[1]*H[1]+Nf[2]*H[2]; if(spec<0)spec=0;
    const inten=Math.pow(spec,3);
    if(inten>0.003){
      const aH=Math.max(-1.05,Math.min(1.05,(Ux[0]*H[0]+Ux[1]*H[1]+Ux[2]*H[2])*1.05));
      const bH=Math.max(-1.05,Math.min(1.05,(Vy[0]*H[0]+Vy[1]*H[1]+Vy[2]*H[2])*1.05));
      const px=faceCx+aH*R*su[0]+bH*R*sv[0];
      const py=faceCy+aH*R*su[1]+bH*R*sv[1];
      ctx.globalCompositeOperation='lighter';
      ctx.fillStyle=`rgba(255,248,225,${0.09*spec})`; ctx.fill(facePath);
      const gr=ctx.createRadialGradient(px,py,0,px,py,R*0.62);
      gr.addColorStop(0,`rgba(255,252,238,${0.95*inten})`);
      gr.addColorStop(0.35,`rgba(255,246,214,${0.4*inten})`);
      gr.addColorStop(1,'rgba(255,246,214,0)');
      ctx.fillStyle=gr; ctx.fill(facePath);
      ctx.globalCompositeOperation='source-over';
    }
    ctx.restore();
  };

  for(const op of ops){
    if(op.type==='face') drawFace();
    else{
      ctx.beginPath();
      ctx.moveTo(op.pts[0][0],op.pts[0][1]);
      for(let j=1;j<4;j++)ctx.lineTo(op.pts[j][0],op.pts[j][1]);
      ctx.closePath(); ctx.fillStyle=op.col; ctx.fill();
    }
  }
}

